
-- Read-only, immediately after installation and before opening financial writes.
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path=public,pg_catalog;
DO $post$ DECLARE rel regclass; n text; f jsonb; BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM primeline_debitos_20261011.controlo WHERE singleton AND state='applied') THEN RAISE EXCEPTION 'APPLIED_BACKUP_REQUIRED'; END IF;
 IF (SELECT data_debitos FROM primeline_debitos_20261011.controlo) IS DISTINCT FROM (SELECT coalesce(jsonb_agg(to_jsonb(d)-'empresa_id' ORDER BY id),'[]') FROM public.debitos_diretos d) OR (SELECT data_lancamentos FROM primeline_debitos_20261011.controlo) IS DISTINCT FROM (SELECT coalesce(jsonb_agg(to_jsonb(l)-'empresa_id' ORDER BY id),'[]') FROM public.debitos_diretos_lancamentos l) THEN RAISE EXCEPTION 'HISTORICAL_DATA_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM public.debitos_diretos d LEFT JOIN public.obras o ON o.id=d.obra_id LEFT JOIN public.empresas e ON e.id=o.empresa_id WHERE d.empresa_id IS DISTINCT FROM e.id) OR EXISTS(SELECT 1 FROM public.debitos_diretos_lancamentos l JOIN public.debitos_diretos d ON d.id=l.debito_direto_id WHERE l.empresa_id IS DISTINCT FROM d.empresa_id) THEN RAISE EXCEPTION 'BACKFILL_NOT_EXCLUSIVELY_A'; END IF;
 FOREACH n IN ARRAY ARRAY['debitos_diretos','debitos_diretos_lancamentos'] LOOP
  rel:=('public.'||n)::regclass;
  IF NOT (SELECT relrowsecurity AND relowner='postgres'::regrole FROM pg_class WHERE oid=rel) THEN RAISE EXCEPTION 'OWNER_RLS_DRIFT'; END IF;
  IF NOT has_table_privilege('authenticated',rel,'SELECT') OR NOT has_table_privilege('authenticated',rel,'INSERT') OR has_table_privilege('authenticated',rel,'UPDATE,DELETE,TRUNCATE') OR has_table_privilege('anon',rel,'SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('service_role',rel,'SELECT,INSERT,UPDATE,DELETE') THEN RAISE EXCEPTION 'TARGET_ACL_DRIFT'; END IF;
  IF EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=rel AND attnum>0 AND attacl IS NOT NULL) THEN RAISE EXCEPTION 'COLUMN_ACL_DRIFT'; END IF;
  IF (SELECT count(*) FROM pg_policy WHERE polrelid=rel AND NOT polpermissive AND polcmd='*')<>1 OR (SELECT count(*) FROM pg_policy WHERE polrelid=rel)<>3 THEN RAISE EXCEPTION 'TENANT_POLICY_MISSING'; END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=rel AND NOT tgisinternal AND tgname=CASE WHEN n='debitos_diretos' THEN 'trg_00_dd_tenant' ELSE 'trg_00_ddl_tenant' END AND tgenabled='O' AND tgfoid='financeiro_debitos_privado.guarda()'::regprocedure) THEN RAISE EXCEPTION 'TENANT_GUARD_MISSING'; END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=rel AND NOT tgisinternal AND tgname='trg_auditoria_'||n AND tgenabled='O' AND tgfoid='public.fn_registar_log_auditoria()'::regprocedure) THEN RAISE EXCEPTION 'AUDIT_MISSING'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_namespace WHERE nspname IN('financeiro_debitos_privado','primeline_debitos_20261011') AND (nspowner<>'postgres'::regrole OR has_schema_privilege('authenticated',oid,'USAGE') OR has_schema_privilege('anon',oid,'USAGE') OR has_schema_privilege('service_role',oid,'USAGE'))) THEN RAISE EXCEPTION 'PRIVATE_SCHEMA_EXPOSED'; END IF;
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN('financeiro_debitos_privado','primeline_debitos_20261011') AND c.relkind='r' AND (NOT c.relrowsecurity OR has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('service_role',c.oid,'SELECT,INSERT,UPDATE,DELETE'))) THEN RAISE EXCEPTION 'PRIVATE_TABLE_EXPOSED'; END IF;
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='financeiro_debitos_privado' AND (has_function_privilege('authenticated',p.oid,'EXECUTE') OR has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('service_role',p.oid,'EXECUTE'))) THEN RAISE EXCEPTION 'PRIVATE_FUNCTION_EXPOSED'; END IF;
 FOR f IN SELECT value FROM jsonb_array_elements($contract$[{"signature": "fn_e_administrativo()", "hash": "c6fa029ddf68fac866607408dcb2069f594c9f0c571de513616ed0a1c45bde82"}, {"signature": "fn_e_financeiro()", "hash": "f82ccdf4944e01e45091a93f402d685af2b9c46ae5c07073f16daf0bd8bd2ff3"}, {"signature": "fn_economico_ator_atual()", "hash": "cd08aba6e6d90349350e53032199586dda6f42679fd1ba500b3758543b657e69"}, {"signature": "fn_financeiro_autorizar_obra(uuid,boolean)", "hash": "53224866b2c7c7dfb6e620305327ecee0a01816c97987b62ad08b5f29c38daad"}, {"signature": "fn_importar_mapa_financeiro_xlsx(integer,jsonb,text)", "hash": "c832589ad6ddde447c94a350e90183f19fe10a4f15cd7647c9dd51dc4160e28d"}, {"signature": "fn_log_importacao_xlsx(text,text,integer,jsonb)", "hash": "6a068375c1a8b09e41c3db1700509599b34597db440761bbc65a5c684ba6d457"}, {"signature": "fn_utilizador_atual_id()", "hash": "299b4257f69e299760e1d925ca3b2e49ce5665dc5e02fba34fb7597cb71947be"}]$contract$::jsonb) LOOP
  IF encode(sha256(convert_to(replace(pg_get_functiondef(to_regprocedure(f->>'signature')),chr(13),''),'UTF8')),'hex') IS DISTINCT FROM f->>'hash' THEN RAISE EXCEPTION 'UNRELATED_HELPER_CHANGED: %',f->>'signature'; END IF;
 END LOOP;
 FOREACH n IN ARRAY ARRAY['fn_debitos_tenant_leitura(uuid,uuid)','fn_despesas_gerais_importar_v1(integer,jsonb,text,uuid,boolean,text,boolean)','fn_despesas_gerais_reverter_v1(uuid,uuid,text,boolean,text)'] LOOP
  IF NOT has_function_privilege('authenticated',n,'EXECUTE') OR has_function_privilege('anon',n,'EXECUTE') OR has_function_privilege('service_role',n,'EXECUTE') OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=n::regprocedure AND prosecdef AND proowner='postgres'::regrole AND proconfig=ARRAY['search_path=pg_catalog']) THEN RAISE EXCEPTION 'PUBLIC_RPC_CONTRACT_DRIFT: %',n; END IF;
 END LOOP;
END $post$;

DO $catalog$ DECLARE t jsonb; c jsonb; p jsonb; tr jsonb; rel regclass; actual jsonb; BEGIN
 FOR t IN SELECT value FROM jsonb_array_elements($tables$[{"acl": "{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,authenticated=ar/postgres}", "rls": true, "kind": "r", "name": "debitos_diretos", "owner": "postgres", "schema": "public", "columns": [{"acl": null, "name": "id", "type": "uuid", "default": "gen_random_uuid()", "nullable": false}, {"acl": null, "name": "obra_id", "type": "uuid", "default": null, "nullable": true}, {"acl": null, "name": "descricao", "type": "text", "default": null, "nullable": false}, {"acl": null, "name": "categoria", "type": "text", "default": null, "nullable": true}, {"acl": null, "name": "valor_previsto", "type": "numeric", "default": null, "nullable": false}, {"acl": null, "name": "recorrencia", "type": "text", "default": null, "nullable": true}, {"acl": null, "name": "dia_mes", "type": "integer", "default": null, "nullable": true}, {"acl": null, "name": "data_inicio", "type": "date", "default": null, "nullable": false}, {"acl": null, "name": "data_fim", "type": "date", "default": null, "nullable": true}, {"acl": null, "name": "ativo", "type": "boolean", "default": "true", "nullable": false}, {"acl": null, "name": "criado_por", "type": "uuid", "default": null, "nullable": true}, {"acl": null, "name": "criado_em", "type": "timestamp with time zone", "default": "now()", "nullable": false}], "indexes": [{"valid": true, "definition": "CREATE UNIQUE INDEX debitos_diretos_pkey ON public.debitos_diretos USING btree (id)"}], "policies": [{"cmd": "INSERT", "qual": null, "roles": ["authenticated"], "tablename": "debitos_diretos", "permissive": "PERMISSIVE", "policyname": "pl_debitos_diretos_insert", "schemaname": "public", "with_check": "(fn_e_administrativo() OR fn_e_financeiro())"}, {"cmd": "SELECT", "qual": "(fn_e_administrativo() OR fn_e_financeiro() OR ((obra_id IS NOT NULL) AND fn_pode_ver_obra(obra_id)))", "roles": ["authenticated"], "tablename": "debitos_diretos", "permissive": "PERMISSIVE", "policyname": "pl_debitos_diretos_select", "schemaname": "public", "with_check": null}], "triggers": [{"name": "trg_auditoria_debitos_diretos", "enabled": "O", "function": "fn_registar_log_auditoria()", "definition": "CREATE TRIGGER trg_auditoria_debitos_diretos AFTER INSERT OR DELETE OR UPDATE ON public.debitos_diretos FOR EACH ROW EXECUTE FUNCTION fn_registar_log_auditoria('id')"}], "force_rls": false, "constraints": [{"name": "debitos_diretos_categoria_check", "type": "c", "validated": true, "definition": "CHECK ((categoria = ANY (ARRAY['renda'::text, 'seguro'::text, 'software'::text, 'emprestimo'::text, 'servico_publico'::text, 'remuneracoes_sede'::text, 'despesas_sede'::text, 'despesas_armazem'::text, 'outro'::text])))"}, {"name": "debitos_diretos_criado_por_fkey", "type": "f", "validated": true, "definition": "FOREIGN KEY (criado_por) REFERENCES utilizadores(id)"}, {"name": "debitos_diretos_dia_mes_check", "type": "c", "validated": true, "definition": "CHECK (((dia_mes >= 1) AND (dia_mes <= 31)))"}, {"name": "debitos_diretos_obra_id_fkey", "type": "f", "validated": true, "definition": "FOREIGN KEY (obra_id) REFERENCES obras(id)"}, {"name": "debitos_diretos_pkey", "type": "p", "validated": true, "definition": "PRIMARY KEY (id)"}, {"name": "debitos_diretos_recorrencia_check", "type": "c", "validated": true, "definition": "CHECK ((recorrencia = ANY (ARRAY['mensal'::text, 'trimestral'::text, 'anual'::text])))"}], "view_definition": null}, {"acl": "{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,authenticated=ar/postgres}", "rls": true, "kind": "r", "name": "debitos_diretos_lancamentos", "owner": "postgres", "schema": "public", "columns": [{"acl": null, "name": "id", "type": "uuid", "default": "gen_random_uuid()", "nullable": false}, {"acl": null, "name": "debito_direto_id", "type": "uuid", "default": null, "nullable": false}, {"acl": null, "name": "data", "type": "date", "default": null, "nullable": false}, {"acl": null, "name": "valor", "type": "numeric", "default": null, "nullable": false}, {"acl": null, "name": "criado_em", "type": "timestamp with time zone", "default": "now()", "nullable": false}], "indexes": [{"valid": true, "definition": "CREATE UNIQUE INDEX debitos_diretos_lancamentos_debito_direto_id_data_key ON public.debitos_diretos_lancamentos USING btree (debito_direto_id, data)"}, {"valid": true, "definition": "CREATE UNIQUE INDEX debitos_diretos_lancamentos_pkey ON public.debitos_diretos_lancamentos USING btree (id)"}], "policies": [{"cmd": "INSERT", "qual": null, "roles": ["authenticated"], "tablename": "debitos_diretos_lancamentos", "permissive": "PERMISSIVE", "policyname": "pl_debitos_lancamentos_insert", "schemaname": "public", "with_check": "(fn_e_administrativo() OR fn_e_financeiro())"}, {"cmd": "SELECT", "qual": "(EXISTS ( SELECT 1\n   FROM debitos_diretos d\n  WHERE ((d.id = debitos_diretos_lancamentos.debito_direto_id) AND (fn_e_administrativo() OR fn_e_financeiro() OR ((d.obra_id IS NOT NULL) AND fn_pode_ver_obra(d.obra_id))))))", "roles": ["authenticated"], "tablename": "debitos_diretos_lancamentos", "permissive": "PERMISSIVE", "policyname": "pl_debitos_lancamentos_select", "schemaname": "public", "with_check": null}], "triggers": [{"name": "trg_auditoria_debitos_diretos_lancamentos", "enabled": "O", "function": "fn_registar_log_auditoria()", "definition": "CREATE TRIGGER trg_auditoria_debitos_diretos_lancamentos AFTER INSERT OR DELETE OR UPDATE ON public.debitos_diretos_lancamentos FOR EACH ROW EXECUTE FUNCTION fn_registar_log_auditoria('id')"}], "force_rls": false, "constraints": [{"name": "debitos_diretos_lancamentos_debito_direto_id_data_key", "type": "u", "validated": true, "definition": "UNIQUE (debito_direto_id, data)"}, {"name": "debitos_diretos_lancamentos_debito_direto_id_fkey", "type": "f", "validated": true, "definition": "FOREIGN KEY (debito_direto_id) REFERENCES debitos_diretos(id) ON DELETE CASCADE"}, {"name": "debitos_diretos_lancamentos_pkey", "type": "p", "validated": true, "definition": "PRIMARY KEY (id)"}], "view_definition": null}]$tables$::jsonb) LOOP
  rel:=('public.'||(t->>'name'))::regclass;
  IF (SELECT relforcerowsecurity FROM pg_class WHERE oid=rel) IS DISTINCT FROM (t->>'force_rls')::boolean THEN RAISE EXCEPTION 'FORCE_RLS_DRIFT: %',rel; END IF;
  FOR c IN SELECT value FROM jsonb_array_elements(t->'columns') LOOP
   SELECT jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'nullable',NOT a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl::text) INTO actual FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=rel AND a.attname=c->>'name' AND NOT a.attisdropped;
   IF actual IS DISTINCT FROM c-'name' THEN RAISE EXCEPTION 'COLUMN_CONTRACT_DRIFT: %.%',rel,c->>'name'; END IF;
  END LOOP;
  IF (SELECT count(*) FROM pg_policy WHERE polrelid=rel)<>jsonb_array_length(t->'policies')+1 THEN RAISE EXCEPTION 'POLICY_COUNT_DRIFT: %',rel; END IF;
  FOR p IN SELECT value FROM jsonb_array_elements(t->'policies') LOOP
   SELECT to_jsonb(v) INTO actual FROM pg_policies v WHERE schemaname='public' AND tablename=t->>'name' AND policyname=p->>'policyname';
   IF actual IS DISTINCT FROM p THEN RAISE EXCEPTION 'POLICY_CONTRACT_DRIFT: %.%',rel,p->>'policyname'; END IF;
  END LOOP;
  IF (SELECT count(*) FROM pg_constraint WHERE conrelid=rel)<>jsonb_array_length(t->'constraints')+(CASE WHEN t->>'name'='debitos_diretos' THEN 2 ELSE 3 END) THEN RAISE EXCEPTION 'CONSTRAINT_COUNT_DRIFT: %',rel; END IF;
  FOR c IN SELECT value FROM jsonb_array_elements(t->'constraints') LOOP
   IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=rel AND conname=c->>'name' AND contype::text=c->>'type' AND convalidated=(c->>'validated')::boolean AND pg_get_constraintdef(oid)=c->>'definition') THEN RAISE EXCEPTION 'CONSTRAINT_CONTRACT_DRIFT: %.%',rel,c->>'name'; END IF;
  END LOOP;
  IF (SELECT count(*) FROM pg_trigger WHERE tgrelid=rel AND NOT tgisinternal)<>jsonb_array_length(t->'triggers')+1 THEN RAISE EXCEPTION 'TRIGGER_COUNT_DRIFT: %',rel; END IF;
  FOR tr IN SELECT value FROM jsonb_array_elements(t->'triggers') LOOP
   IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=rel AND tgname=tr->>'name' AND tgenabled::text=tr->>'enabled' AND pg_get_triggerdef(oid)=tr->>'definition') THEN RAISE EXCEPTION 'AUDIT_TRIGGER_DRIFT: %',rel; END IF;
  END LOOP;
 END LOOP;
END $catalog$;

DO $source_check$ DECLARE f jsonb; BEGIN
 FOR f IN SELECT value FROM jsonb_array_elements($sources$[{"name": "financeiro_debitos_privado.ator", "sha256": "8e64576a57e1f989721974591464c6883e54b57cd17dd7ebc9119715acc2e9a4"}, {"name": "public.fn_debitos_tenant_leitura", "sha256": "f407af89e400e0dd3a2c370429c1be1c148de231f95ab277f502342b81af05d7"}, {"name": "financeiro_debitos_privado.guarda", "sha256": "85526477437c093ef50320a653570a8f77565d552af236fcd3fd82b31b0801ec"}, {"name": "financeiro_debitos_privado.mac", "sha256": "d90cddb253ce86cb90676b7fcc1a42141c8d9ed75947a6b1961cb4764203c96d"}, {"name": "financeiro_debitos_privado.snapshot", "sha256": "c03de21d7d40c350ab9dc9f666a2108728168d7440a8957d83451a5304f18030"}, {"name": "public.fn_despesas_gerais_importar_v1", "sha256": "284ee3c44553206301acedea8495105cb8fe65ff3e6b0ef866bb9b0d08ca394b"}, {"name": "public.fn_despesas_gerais_reverter_v1", "sha256": "f978efcd0596045d00831b0f483546c23b2dd3b1e639c34d7654d76fe0155225"}]$sources$::jsonb) LOOP
  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname=f->>'name')<>1 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname=f->>'name' AND p.proowner='postgres'::regrole AND p.prosecdef AND p.proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(p.prosrc,chr(13),''),'UTF8')),'hex')=f->>'sha256') THEN RAISE EXCEPTION 'NEW_FUNCTION_SOURCE_DRIFT: %',f->>'name'; END IF;
 END LOOP;
END $source_check$;

DO $policies$ DECLARE expected jsonb; actual jsonb; BEGIN
 FOR expected IN SELECT value FROM jsonb_array_elements($policy_json$[{"schemaname": "public", "tablename": "debitos_diretos", "policyname": "dd_tenant_restrito", "permissive": "RESTRICTIVE", "roles": ["authenticated"], "cmd": "ALL", "qual": "fn_debitos_tenant_leitura(empresa_id, obra_id)", "with_check": "fn_debitos_tenant_leitura(empresa_id, obra_id)"}, {"schemaname": "public", "tablename": "debitos_diretos_lancamentos", "policyname": "ddl_tenant_restrito", "permissive": "RESTRICTIVE", "roles": ["authenticated"], "cmd": "ALL", "qual": "((empresa_id IS NOT NULL) AND (EXISTS ( SELECT 1\n   FROM debitos_diretos d\n  WHERE ((d.id = debitos_diretos_lancamentos.debito_direto_id) AND (d.empresa_id = debitos_diretos_lancamentos.empresa_id)))))", "with_check": "((empresa_id IS NOT NULL) AND (EXISTS ( SELECT 1\n   FROM debitos_diretos d\n  WHERE ((d.id = debitos_diretos_lancamentos.debito_direto_id) AND (d.empresa_id = debitos_diretos_lancamentos.empresa_id)))))"}]$policy_json$::jsonb) LOOP
  SELECT to_jsonb(v) INTO actual FROM pg_policies v WHERE schemaname='public' AND tablename=expected->>'tablename' AND policyname=expected->>'policyname';
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'TENANT_POLICY_DEFINITION_DRIFT: %',expected->>'policyname'; END IF;
 END LOOP;
END $policies$;
SELECT 'FINANCEIRO_DEBITOS_POSTCHECK_OK' resultado;
COMMIT;
